        {
            Question = q;
            Choices = new string[choices.Length];
            for (int i = 0; i < choices.Length; i++)
                Choices[i] = choices[i] ? "A" : "B";
            CorrectChoice = choices.ToList().IndexOf(true) + 1;
        }

        public string GetHtml()
        {
            var sb = new StringBuilder();
            sb.AppendFormat("<p>{0}</p>", Question);
            for (int i = 0; i < Choices.Length; i++)
                sb.AppendFormat("<p><input type=\"radio\" name=\"q1\" value=\"{0}\" />{1}. {2}</p>", i + 1, i + 1, Choices[i]);
            return sb.ToString();
        }
    }
